use std::collections::HashMap;

fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {
    if n <= 2 {
        return 1;
    }
    if let Some(&value) = memo.get(&n) {
        return value;
    }
    let value = fib(n - 1, memo) + fib(n - 2, memo);
    memo.insert(n, value);
    value
}

fn main() {
    let mut memo = HashMap::new();
    for n in 1..=20 {
        println!("fib({}) = {}", n, fib(n, &mut memo));
    }
}

use std::env;
use std::error::Error;

fn eval(expr: &str) -> Result<f64, Box<dyn Error>> {
    let mut stack: Vec<f64> = Vec::new();

    for token in expr.split_whitespace() {
        match token {
            "+" | "-" | "*" | "/" => {
                let b = stack.pop().ok_or("stack underflow")?;
                let a = stack.pop().ok_or("stack underflow")?;
                let result = match token {
                    "+" => a + b,
                    "-" => a - b,
                    "*" => a * b,
                    "/" => {
                        if b == 0.0 {
                            return Err("division by zero".into());
                        }
                        a / b
                    }
                    _ => unreachable!(),
                };
                stack.push(result);
            }
            _ => {
                let value: f64 = token
                    .parse()
                    .map_err(|_| format!("invalid token: {token}"))?;
                stack.push(value);
            }
        }
    }

    match stack.as_slice() {
        [result] => Ok(*result),
        _ => Err("malformed expression".into()),
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let expr = env::args().nth(1).ok_or("usage: rpn \"<expression>\"")?;
    println!("{}", eval(&expr)?);
    Ok(())
}

