use std::collections::HashMap;

fn fib(n: u32, memo: &mut HashMap<u32, u64>) -> u64 {
    if let Some(&result) = memo.get(&n) {
        return result;
    }

    let result = if n == 1 || n == 2 {
        1
    } else {
        fib(n - 1, memo) + fib(n - 2, memo)
    };

    memo.insert(n, result);
    result
}

fn main() {
